const $ = (sel) => document.querySelector(sel);

const inp = $('#inp');
const outTokens = $('#outTokens');
const outToggle = $('#outToggle');
const outAccent = $('#outAccent');
const outWarn = $('#outWarn');

const verb = $('#verb');
const outMake = $('#outMake');

// --- Greek helpers (toy-level) ---
const COMBINING = /[\u0300-\u036f]/g;

function nfd(s){ return (s||'').normalize('NFD'); }
function nfc(s){ return (s||'').normalize('NFC'); }

function stripCombining(s){ return nfd(s).replace(COMBINING,''); }

function stripPunctKeepGreek(s){
  // Keep Greek letters, spaces, apostrophes, and basic hyphen; drop other punctuation.
  // This is intentionally permissive.
  return (s||'')
    .replace(/[“”"\(\)\[\]{}<>··;:,.!?…]/g,' ')
    .replace(/\s+/g,' ')
    .trim();
}

function tokenizeWords(s){
  s = stripPunctKeepGreek(s);
  if(!s) return [];
  return s.split(' ').filter(Boolean);
}

function endsWithRos(word){
  const base = stripCombining(word).toLowerCase();
  return base.endsWith('ρος');
}

function highlightEiI(word){
  // Highlight occurrences of ει and ι (toy)
  const raw = nfd(word);
  // Work on stripped-combining for matching, but keep original by mapping indices roughly.
  // Simpler: do a second pass on NFC and use regex that matches both composed and decomposed.
  let w = nfc(word);
  // Highlight ει first
  w = w.replace(/ει/g, (m)=>`<mark class="hl ei">${m}</mark>`);
  // Then highlight remaining iota (ι/ί/ὶ/ῖ/ϊ/ΐ) by matching base iota plus optional tonos/diaeresis.
  // We'll do it on NFD to catch combining marks, then recompose.
  let wN = nfd(w);
  // Replace standalone iota letter (U+03B9 or U+0399) not already inside a mark tag.
  // Since we injected HTML, avoid touching tags by splitting on <...>.
  const parts = wN.split(/(<[^>]+>)/g);
  for(let i=0;i<parts.length;i++){
    if(parts[i].startsWith('<')) continue;
    parts[i] = parts[i].replace(/([Ιι])([\u0300-\u036f]*)/g, (full, letter, comb)=>{
      const chunk = nfc(letter + comb);
      return `<mark class="hl i">${chunk}</mark>`;
    });
  }
  return nfc(parts.join(''));
}

function countVowelGroups(word){
  // Rough syllable proxy: count vowel groups in stripped word.
  const w = stripCombining(word).toLowerCase();
  // Greek vowels incl. ωηοεαυι + diphthong-ish sequences treated as one group by regex.
  // This is a toy; we just count groups of vowel letters.
  const m = w.match(/[αεηιουω]+/g);
  return m ? m.length : 0;
}

function hasPenultEiOrLongI(word){
  // Toy: if the word ends in -ρος, look for ει or ι in the syllable before -ρος.
  // We'll approximate by checking the last 4-6 letters.
  const w = stripCombining(word).toLowerCase();
  if(!w.endsWith('ρος')) return false;
  const tail = w.slice(-6); // e.g. καμειρος
  return tail.includes('ειρ') || tail.includes('ιρ');
}

function togglePrefer(word, mode){
  // mode: 'ei' or 'i'
  // Replace occurrences of ει before ρ with ι, or ι before ρ with ει.
  // Also handle plural Καβείρους etc by targeting ειρ / ιρ sequences.
  let w = nfc(word);
  if(mode==='i'){
    w = w.replace(/ει(?=ρ)/g,'ι');
    w = w.replace(/Ει(?=ρ)/g,'Ι');
  } else {
    w = w.replace(/ι(?=ρ)/g,'ει');
    w = w.replace(/Ι(?=ρ)/g,'Ει');
  }
  return w;
}

function accentGuess(word){
  // Very rough: if -ρος and (>=3 syllable groups) and penult has ει or ι, guess barytone.
  // We'll output a suggested accent on the antepenult if possible; else on penult.
  const clean = stripPunctKeepGreek(word);
  const w = clean;
  const info = { ok:false, reason:'', suggested:'', type:'' };
  if(!w){ info.reason='Type something.'; return info; }
  if(!endsWithRos(w)){
    info.reason='Not a -ρος word (toy only checks -ρος).';
    return info;
  }
  const syl = countVowelGroups(w);
  const longish = hasPenultEiOrLongI(w);
  info.type = `-ρος; vowel-groups≈${syl}; penult has ει/ι? ${longish?'yes':'no'}`;

  // Decide barytone vs oxytone guess
  const bary = (syl>=3 && longish);
  info.ok = true;

  // Build a naive accent placement by adding an acute to a target vowel in the word.
  // We do not attempt correct recessive rules; just a visible suggestion.
  const target = bary ? 'antepenult' : 'ultima';
  info.reason = bary
    ? 'Guess: βαρυτονία (not final accent), inspired by Herodian’s note about long penult (ει/ι) in longer -ρος forms.'
    : 'Guess: could be oxytone or mixed; toy does not see the “Herodian trigger” clearly.';

  info.suggested = addToyAcute(w, target);
  return info;
}

function addToyAcute(word, where){
  // Add acute to first vowel of chosen syllable (ultima/penult/antepenult) using a crude syllable split.
  // We split by vowel groups in stripped text, then map back to original by scanning.
  const wN = nfd(word);
  const base = stripCombining(word);
  const vowels = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);

  // Find vowel-group start indices in base
  const starts = [];
  let inV = false;
  for(let i=0;i<base.length;i++){
    const ch = base[i];
    const isV = vowels.has(ch);
    if(isV && !inV) starts.push(i);
    inV = isV;
  }
  if(starts.length===0) return word;

  let idx;
  if(where==='ultima') idx = starts[starts.length-1];
  else if(where==='penult') idx = starts[Math.max(0, starts.length-2)];
  else idx = starts[Math.max(0, starts.length-3)];

  // Map base index to NFD index by scanning letters and skipping combining marks.
  let basePos = 0;
  let nfdPos = 0;
  while(nfdPos < wN.length && basePos < idx){
    const c = wN[nfdPos];
    if(!c.match(COMBINING)) basePos++;
    nfdPos++;
  }

  // Now at the target base letter in NFD; add combining acute U+0301 after the letter and any existing combining marks.
  // If there is already an accent mark, leave as-is.
  const existing = /[\u0300\u0301\u0342]/; // grave, acute, circumflex
  let j = nfdPos+1;
  while(j < wN.length && wN[j].match(COMBINING)){
    if(existing.test(wN[j])) return word; // already accented
    j++;
  }
  const out = wN.slice(0,j) + '\u0301' + wN.slice(j);
  return nfc(out);
}

function renderAnalysis(){
  const words = tokenizeWords(inp.value);
  if(words.length===0){
    outTokens.textContent = '—';
    outToggle.textContent = '—';
    outAccent.textContent = '—';
    outWarn.textContent = '';
    return;
  }

  const lines = [];
  for(const w of words){
    const syl = countVowelGroups(w);
    const ros = endsWithRos(w);
    const longish = hasPenultEiOrLongI(w);
    lines.push(`${w}  | -ρος? ${ros?'yes':'no'} | vowel-groups≈${syl} | penult ει/ι? ${longish?'yes':'no'}`);
  }
  outTokens.textContent = lines.join('\n');

  // Toggle preview uses first word
  const w0 = words[0];
  const toEi = togglePrefer(w0,'ei');
  const toI = togglePrefer(w0,'i');
  outToggle.innerHTML = `prefer ει → ${highlightEiI(toEi)}\nprefer ι  → ${highlightEiI(toI)}`;

  // Accent guess uses first word
  const g = accentGuess(w0);
  if(!g.ok){
    outAccent.textContent = g.reason;
    outWarn.textContent = '';
  } else {
    outAccent.innerHTML = `${g.reason}\n${g.type}\nSuggested: <b>${highlightEiI(g.suggested)}</b>`;
    outWarn.textContent = 'Reminder: this is a toy. Real accentuation depends on quantity, morphology, and tradition.';
  }
}

// --- Verbal -ειρος maker (toy) ---
function makeEirosFromVerb(v){
  v = stripPunctKeepGreek(v);
  if(!v) return {out:'—', note:'Type a verb.'};
  const base = stripCombining(v).toLowerCase();

  // crude stem heuristics
  let stem = v;
  let note = 'Toy rule: remove a final -ω/-ο/-μι/-σω/-ττω if present, then add -ειρος.';

  // Normalize common ASCII-ish inputs: allow "ϊ" typed as "i"? we won't.

  // Remove final omega/omicron
  if(/[ωο]$/.test(base)){
    stem = v.slice(0, v.length-1);
  }
  // Remove -σω
  if(base.endsWith('σω')){
    stem = v.slice(0, v.length-2);
  }
  // Remove -ττω
  if(base.endsWith('ττω')){
    stem = v.slice(0, v.length-3);
  }
  // Remove -σσω
  if(base.endsWith('σσω')){
    stem = v.slice(0, v.length-3);
  }
  // Remove -μι
  if(base.endsWith('μι')){
    stem = v.slice(0, v.length-2);
  }

  let out = nfc(stem + 'ειρος');

  // Add a toy accent: try antepenult (barytone-ish)
  out = addToyAcute(out,'antepenult');

  return {out, note};
}

function renderMake(){
  const r = makeEirosFromVerb(verb.value);
  outMake.innerHTML = `${r.note}\nResult: <b>${highlightEiI(r.out)}</b>`;
}

// --- Events ---
$('#btnAnalyze').addEventListener('click', renderAnalysis);
$('#btnClear').addEventListener('click', ()=>{ inp.value=''; renderAnalysis(); inp.focus(); });

$('#btnToEi').addEventListener('click', ()=>{
  const words = tokenizeWords(inp.value);
  if(words.length===0) return;
  words[0] = togglePrefer(words[0],'ei');
  inp.value = words.join(' ');
  renderAnalysis();
});
$('#btnToI').addEventListener('click', ()=>{
  const words = tokenizeWords(inp.value);
  if(words.length===0) return;
  words[0] = togglePrefer(words[0],'i');
  inp.value = words.join(' ');
  renderAnalysis();
});

$('#btnMake').addEventListener('click', renderMake);
$('#btnExamples').addEventListener('click', ()=>{
  verb.value = 'μασσω';
  renderMake();
});

// chips
for(const chip of document.querySelectorAll('.chip')){
  chip.addEventListener('click', ()=>{
    verb.value = chip.getAttribute('data-fill');
    renderMake();
  });
}

// live-ish updates
inp.addEventListener('input', ()=>{ renderAnalysis(); });
verb.addEventListener('input', ()=>{ renderMake(); });

// init
renderAnalysis();
renderMake();

