  info.reason = bary
    ? 'Guess: βαρυτονία (not final accent), inspired by Herodian’s note about long penult (ει/ι) in longer -ρος forms.'
    : 'Guess: could be oxytone or mixed; toy does not see the “Herodian trigger” clearly.';

  info.suggested = addToyAcute(w, target);
  return info;
}

function addToyAcute(word, where){
  // Add acute to first vowel of chosen syllable (ultima/penult/antepenult) using a crude syllable split.
  // We split by vowel groups in stripped text, then map back to original by scanning.
  const wN = nfd(word);
  const base = stripCombining(word);
  const vowels = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);

  // Find vowel-group start indices in base
  const starts = [];
  let inV = false;
  for(let i=0;i<base.length;i++){
    const ch = base[i];
    const isV = vowels.has(ch);
    if(isV && !inV) starts.push(i);
    inV = isV;
  }
  if(starts.length===0) return word;

  let idx;
  if(where==='ultima') idx = starts[starts.length-1];
  else if(where==='penult') idx = starts[Math.max(0, starts.length-2)];
  else idx = starts[Math.max(0, starts.length-3)];

  // Map base index to NFD index by scanning letters and skipping combining marks.
  let basePos = 0;
  let nfdPos = 0;
  while(nfdPos < wN.length && basePos < idx){
    const c = wN[nfdPos];
    if(!c.match(COMBINING)) basePos++;
    nfdPos++;
  }

  // Now at the target base letter in NFD; add combining acute U+0301 after the letter and any existing combining marks.
  // If there is already an accent mark, leave as-is.
  const existing = /[\u0300\u0301\u0342]/; // grave, acute, circumflex
  let j = nfdPos+1;
  while(j < wN.length && wN[j].match(COMBINING)){
    if(existing.test(wN[j])) return word; // already accented
    j++;
  }
  const out = wN.slice(0,j) + '\u0301' + wN.slice(j);
  return nfc(out);
}

function renderAnalysis(){
  const words = tokenizeWords(inp.value);
  if(words.length===0){
    outTokens.textContent = '—';
    outToggle.textContent = '—';
    outAccent.textContent = '—';
    outWarn.textContent = '';
    return;
  }

  const lines = [];
  for(const w of words){
    const syl = countVowelGroups(w);
    const ros = endsWithRos(w);
    const longish = hasPenultEiOrLongI(w);
    lines.push(`${w}  | -ρος? ${ros?'yes':'no'} | vowel-groups≈${syl} | penult ει/ι? ${longish?'yes':'no'}`);
  }
  outTokens.textContent = lines.join('\n');

  // Toggle preview uses first word
  const w0 = words[0];
  const toEi = togglePrefer(w0,'ei');
  const toI = togglePrefer(w0,'i');
  outToggle.innerHTML = `prefer ει → ${highlightEiI(toEi)}\nprefer ι  → ${highlightEiI(toI)}`;

  // Accent guess uses first word
  const g = accentGuess(w0);
  if(!g.ok){
    outAccent.textContent = g.reason;
    outWarn.textContent = '';
  } else {
    outAccent.innerHTML = `${g.reason}\n${g.type}\nSuggested: <b>${highlightEiI(g.suggested)}</b>`;
    outWarn.textContent = 'Reminder: this is a toy. Real accentuation depends on quantity, morphology, and tradition.';
  }
}

// --- Verbal -ειρος maker (toy) ---
function makeEirosFromVerb(v){
  v = stripPunctKeepGreek(v);
  if(!v) return {out:'—', note:'Type a verb.'};
  const base = stripCombining(v).toLowerCase();

  // crude stem heuristics
  let stem = v;
  let note = 'Toy rule: remove a final -ω/-ο/-μι/-σω/-ττω if present, then add -ειρος.';

  // Normalize common ASCII-ish inputs: allow "ϊ" typed as "i"? we won't.

  // Remove final omega/omicron
  if(/[ωο]$/.test(base)){
    stem = v.slice(0, v.length-1);
  }
  // Remove -σω
  if(base.endsWith('σω')){
    stem = v.slice(0, v.length-2);
  }
  // Remove -ττω
  if(base.endsWith('ττω')){
    stem = v.slice(0, v.length-3);
  }
  // Remove -σσω
  if(base.endsWith('σσω')){
    stem = v.slice(0, v.length-3);
  }
  // Remove -μι
  if(base.endsWith('μι')){
    stem = v.slice(0, v.length-2);
  }

  let out = nfc(stem + 'ειρος');

  // Add a toy accent: try antepenult (barytone-ish)
  out = addToyAcute(out,'antepenult');

  return {out, note};
}

function renderMake(){
  const r = makeEirosFromVerb(verb.value);
  outMake.innerHTML = `${r.note}\nResult: <b>${highlightEiI(r.out)}</b>`;
}

